        if (255 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 255);
        end
        tested_count = tested_count + 1;

        in_val = 16'd256;
        #1;
