        if (256 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 256);
        end
        tested_count = tested_count + 1;

        in_val = 16'd32767;
        #1;
        // Verify sized expression achieves one-hot
        if (Y_sized[32767] !== 1'b1) begin
            $display("ERROR_SIZED: in=%0d Y_sized[%0d]=%b (expected 1)", in_val, 32767, Y_sized[32767]);
            err_sized = err_sized + 1;
        end
        // Compare with unsafe 1'b1 shift
        // In self-determined context, 1'b1 << s evaluates as 1-bit and produces 0 for s > 0
        if (32767 > 0 && (1'b1 << in_val) !== 1'b0) begin
            $display("NOTE: 1'b1 << %0d did not truncate to 0 as expected in Verilog", 32767);
